// mixedAssertNewInputZeroOnError asserts NewInput returns zero alongside any error.
func mixedAssertNewInputZeroOnError(
	tb testing.TB,
	m Mixed,
) {
	tb.Helper()
	ctx, cancel := context.WithCancel(tb.Context())
	cancel()
	got, err := m.NewInput(ctx)
	if err == nil {
		tb.Skip("NewInput answered for a cancelled context, so this check has no error to inspect")
	}

	var zero string
	if got != zero {
		tb.Errorf("NewInput must return the zero value alongside an error: got %+v, want %+v (err %v)",
			got, zero, err)
	}
}

